1	/**
2	 * The §15 harness agent loop — "implements its own minimal tool-use loop"
3	 * (packages/mcp contract). Each scenario runs twice on the same frontier model:
4	 *
5	 *   native        full-transcript context. The message list grows every turn;
6	 *                 tools are the four harness tools only.
7	 *   context-tree  the tree IS the context. Every turn's events are appended to
8	 *                 L0 via `appendEvent`, the §8 summarizer refreshes stale
9	 *                 branches, and the request is assembled by ZoneAssembler
10	 *                 (Zone A contract + schemas, Zone B summaries, Zone C active
11	 *                 branch, tail fetches). The four §9 tools are dispatched
12	 *                 through the same HANDLERS the MCP server registers.
13	 *
14	 * Metrics per run: token totals with the provider's cache split, model turns +
15	 * tool calls, per-turn latency percentiles, and USD cost via InMemoryCostMeter
16	 * over every model call in the run — agent, §8 summarizer and judge alike, so
17	 * the A/B pays for what it actually spends.
18	 */
19	import {
20	  CostCapExceededError,
21	  HeuristicTokenizer,
22	  InMemoryCostMeter,
23	  MeteredProvider,
24	  Summarizer,
25	  TreeRetriever,
26	  ZoneAssembler,
27	  appendEvent,
28	  openTaskStore,
29	  priceFor,
30	  resolveConfig,
31	  systemContract,
32	  toCompletionRequest,
33	  usdFor,
34	  type AppendResult,
35	  type ChatMessage,
36	  type CompletionRequest,
37	  type CompletionResult,
38	  type ContextTreeConfig,
39	  type ModelProvider,
40	  type TaskStore,
41	  type ToolCallRequest,
42	  type TraceEventInput,
43	} from '@context-tree/core';
44	import { HANDLERS, type ToolContext, type ToolName } from '@context-tree/mcp';
45	import {
46	  CONTEXT_TOOL_SCHEMAS,
47	  HARNESS_TOOL_SCHEMAS,
48	  TREE_COMPLETION_ADDENDUM,
49	  TREE_ZONE_A_TOOL_SCHEMAS_TEXT,
50	  executeHarnessTool,
51	  isContextTool,
52	  isHarnessTool,
53	  pathOf,
54	  type ToolCallOutcome,
55	} from './tools.js';
56	import { addTotals, summarizeMetrics, ZERO_TOTALS } from './metrics.js';
57	import { judgeScenario } from './scoring.js';
58	import { createSandbox, type Sandbox } from './sandbox.js';
59	import type { LangfuseRunHandle, LangfuseSink } from './langfuse.js';
60	import type { Arm, HarnessOptions, RunResult, RunStatus, Scenario, TokenTotals, TurnRecord } from './types.js';
61	import { join } from 'node:path';
62	
63	const NATIVE_SYSTEM_PROMPT = [
64	  'You are a capable coding agent working inside a task sandbox.',
65	  'Complete the task using the provided tools. Keep tool outputs and file edits precise,',
66	  'and verify your work by running the relevant commands.',
67	  'When the task is complete, STOP calling tools and reply with your final answer —',
68	  'a reply without tool calls ends the task, so make that reply the deliverable the task asks for.',
69	].join('\n');
70	
71	const AGENT_MAX_TOKENS = 8192;
72	
73	export interface LoopOptions {
74	  runId: string;
75	  scenario: Scenario;
76	  arm: Arm;
77	  agentProvider: ModelProvider;
78	  /**
79	   * The §8 summarizer's provider, separate from the agent's only so an offline
80	   * test can script the two independently. Live runs leave it unset and the
81	   * agent's provider is reused.
82	   */
83	  summarizerProvider?: ModelProvider;
84	  options: HarnessOptions;
85	  sink: LangfuseSink;
86	}
