93	interface ArmArgs {
94	  scenario: Scenario;
95	  config: ContextTreeConfig;
96	  options: HarnessOptions;
97	  provider: ModelProvider;
98	  sandbox: Sandbox;
99	  turns: TurnRecord[];
100	  usage: TokenTotals;
