109	
110	async function callModel(args: {
111	  provider: ModelProvider;
112	  request: CompletionRequest;
113	  turnIndex: number;
114	  runHandle: LangfuseRunHandle;
115	  usage: TokenTotals;
116	}): Promise<{ result: CompletionResult; record: TurnRecord }> {
117	  const startedAt = Date.now();
118	  const result = await args.provider.complete(args.request);
119	  const latencyMs = Math.max(1, Date.now() - startedAt);
120	  const record: TurnRecord = {
121	    index: args.turnIndex,
122	    latencyMs,
123	    usage: result.usage,
124	    toolCalls: result.toolCalls.map((call) => call.name),
125	    stopReason: result.stopReason,
126	  };
127	  args.runHandle.generation({
128	    name: `turn-${args.turnIndex}`,
129	    model: result.model,
130	    input: {
131	      systemChars: args.request.system?.length ?? 0,
132	      messageCount: args.request.messages.length,
133	      tools: args.request.tools?.map((tool) => tool.name) ?? [],
134	    },
135	    output: { textChars: result.text.length, toolCalls: record.toolCalls, stopReason: result.stopReason },
136	    usage: {
137	      input: result.usage.input,
138	      output: result.usage.output,
139	      unit: 'TOKENS',
140	      totalCost: usdFor(result.usage, priceFor(result.model).price),
141	    },
142	    metadata: { cacheRead: result.usage.cacheRead, cacheWrite: result.usage.cacheWrite, latencyMs },
143	  });
144	  return { result, record };
145	}
146	
147	function toolResultMessage(call: ToolCallRequest, outcome: ToolCallOutcome): string {
148	  return `[tool_result ${call.name}] ${outcome.isError ? 'ERROR: ' : ''}${outcome.output}`;
149	}
150	
151	/**
152	 * Repeat-call guard, identical in both arms (so the A/B stays fair): a harness
153	 * capability, not a context feature. Re-issuing a byte-identical tool call is
154	 * the signature of an autopilot loop — the result is already in context — so
155	 * the second call gets guidance instead of another execution.
156	 */
157	export function makeRepeatGuard() {
158	  const seen = new Set<string>();
159	  return (call: ToolCallRequest, execute: () => Promise<ToolCallOutcome>): Promise<ToolCallOutcome> => {
160	    const signature = `${call.name}:${JSON.stringify(call.input)}`;
161	    if (seen.has(signature)) {
162	      return Promise.resolve({
163	        output:
164	          'error: you already ran this exact call and its result is recorded above. ' +
165	          'Repeating it cannot produce new information. Act on the recorded result, or reply with your final answer now.',
166	        isError: true,
167	      });
168	    }
169	    seen.add(signature);
170	    return execute();
171	  };
172	}
173	
174	/**
175	 * DSA arm — DeepSeek-Sparse-Attention-style top-k selection, lifted from token
176	 * space to event space. Vanilla (`native`) attends to the whole transcript; the
177	 * tree attends to a two-level summary. This arm keeps the raw transcript but,
178	 * each turn, scores every past event and injects only the top-k:
179	 *
180	 *   score(event) = w_role + α·recency + β·lexical overlap with the task
181	 *
182	 * with recency = index/total and overlap = shared content words with the task
183	 * text. The caveat the design carries from DSA's sparse-attention kernel: the
184	 * head of the context is NEVER re-selected or re-ordered — the system prompt
185	 * and the first user message (the task) are emitted verbatim at the top every
186	 * turn, so the provider's prompt cache keeps one stable prefix and only the
187	 * tail varies. Selected events are re-emitted in chronological order (the
188	 * model reads a coherent transcript, not a ranking).
189	 *
190	 * The latest turn's tool results are pinned unconditionally: an agent that
191	 * cannot see what its own last action returned loops, and the investigate-1
192	 * incident is the receipt for that failure mode.
193	 */
194	const DSA_TOP_K = 6;
195	const DSA_RECENCY_WEIGHT = 2;
196	const DSA_RELEVANCE_WEIGHT = 3;
197	/**
198	 * The eval floor: below this many tail messages the selector passes the
199	 * transcript through untouched. Filtering only pays when there is something
200	 * worth dropping, and every re-selection moves the cache boundary backwards.
201	 */
202	const DSA_MIN_TAIL = 10;
203	const DSA_ROLE_WEIGHTS: Record<string, number> = { user: 1.5, assistant: 0.5 };
204	
205	const STOP_WORDS = new Set(
206	  ('a an and are as at be by containing exactly file for from in is it named of on or reply that the then this to verify with word you your'
207	    .split(' ')),
208	);
209	
210	export function contentWords(text: string): Set<string> {
211	  const words = new Set<string>();
212	  for (const match of text.toLowerCase().matchAll(/[a-z0-9_.-]{3,}/g)) {
213	    if (!STOP_WORDS.has(match[0])) words.add(match[0]);
214	  }
215	  return words;
216	}
217	
218	function overlapScore(a: Set<string>, b: Set<string>): number {
219	  let shared = 0;
220	  for (const word of a) if (b.has(word)) shared += 1;
221	  return b.size === 0 ? 0 : shared / b.size;
222	}
223	
224	function messageText(message: ChatMessage): string {
225	  return typeof message.content === 'string' ? message.content : JSON.stringify(message.content);
226	}
227	
228	export function selectTopKMessages(
229	  messages: readonly ChatMessage[],
230	  taskWords: Set<string>,
231	  k: number,
232	  minTail: number = DSA_MIN_TAIL,
233	): ChatMessage[] {
234	  const head = messages[0]; // the task — the stable cache prefix ends here
235	  if (head === undefined || messages.length <= 1 + minTail) return [...messages];
236	  const tail = messages.slice(1);
237	  const pinned = Math.min(2, tail.length); // latest tool results / replies, always visible
238	  const pool = tail.slice(0, tail.length - pinned);
239	  const scored = pool.map((message, i) => {
240	    const recency = (i + 1) / pool.length;
241	    const role = DSA_ROLE_WEIGHTS[message.role] ?? 0;
242	    const relevance = overlapScore(contentWords(messageText(message)), taskWords);
243	    return { message, score: role + DSA_RECENCY_WEIGHT * recency + DSA_RELEVANCE_WEIGHT * relevance };
244	  });
245	  const keep = new Set(
246	    scored
247	      .map((entry, index) => ({ ...entry, index }))
248	      .sort((a, b) => b.score - a.score)
249	      .slice(0, Math.max(0, k - pinned))
250	      .map((entry) => entry.index),
251	  );
252	  // Chronological re-emission only within the selected middle: the head is
253	  // fixed and the pinned suffix is the freshest tail, so the selected block
254	  // keeps transcript order.
255	  const selected = pool.filter((_, index) => keep.has(index));
256	  return [head, ...selected, ...tail.slice(tail.length - pinned)];
257	}
258	
259	async function runDsaArm(args: ArmArgs): Promise<ArmOutput> {
260	  const messages: ChatMessage[] = [{ role: 'user', content: args.scenario.task }];
261	  const taskWords = contentWords(args.scenario.task);
262	  const guard = makeRepeatGuard();
263	  let finalText = '';
264	  for (let turnIndex = 0; turnIndex < args.options.maxTurns; turnIndex += 1) {
265	    if (Date.now() >= args.deadlineMs) return { status: 'time_cap', finalText };
266	    const request: CompletionRequest = {
267	      model: args.options.model,
268	      system: NATIVE_SYSTEM_PROMPT,
269	      messages: selectTopKMessages(messages, taskWords, DSA_TOP_K),
270	      tools: HARNESS_TOOL_SCHEMAS,
271	      maxTokens: AGENT_MAX_TOKENS,
272	    };
273	    const { result, record } = await callModel({
274	      provider: args.provider,
275	      request,
276	      turnIndex,
277	      runHandle: args.runHandle,
278	      usage: args.usage,
279	    });
280	    args.turns.push(record);
281	    Object.assign(args.usage, addTotals(args.usage, result.usage));
282	    messages.push({ role: 'assistant', content: result.text });
283	    if (result.toolCalls.length === 0) {
284	      finalText = result.text;
285	      return { status: 'completed', finalText };
286	    }
287	    for (const call of result.toolCalls) {
288	      const outcome = await guard(call, () => executeHarnessTool(args.sandbox, call.name, call.input));
289	      messages.push({ role: 'user', content: toolResultMessage(call, outcome) });
290	    }
291	  }
292	  return { status: 'turn_cap', finalText };
293	}
