296	  const messages: ChatMessage[] = [{ role: 'user', content: args.scenario.task }];
297	  const guard = makeRepeatGuard();
298	  let finalText = '';
299	  for (let turnIndex = 0; turnIndex < args.options.maxTurns; turnIndex += 1) {
300	    if (Date.now() >= args.deadlineMs) return { status: 'time_cap', finalText };
301	    const request: CompletionRequest = {
302	      model: args.options.model,
303	      system: NATIVE_SYSTEM_PROMPT,
304	      messages: [...messages],
305	      tools: HARNESS_TOOL_SCHEMAS,
306	      maxTokens: AGENT_MAX_TOKENS,
307	    };
308	    const { result, record } = await callModel({
