310	      request,
311	      turnIndex,
312	      runHandle: args.runHandle,
313	      usage: args.usage,
314	    });
315	    args.turns.push(record);
316	    Object.assign(args.usage, addTotals(args.usage, result.usage));
317	    messages.push({ role: 'assistant', content: result.text });
318	    if (result.toolCalls.length === 0) {
319	      finalText = result.text;
320	      return { status: 'completed', finalText };
321	    }
322	    for (const call of result.toolCalls) {
323	      const outcome = await guard(call, () => executeHarnessTool(args.sandbox, call.name, call.input));
324	      messages.push({ role: 'user', content: toolResultMessage(call, outcome) });
325	    }
326	  }
