329	
330	function appendTo(handle: TaskStore, input: TraceEventInput): AppendResult {
331	  return appendEvent(handle, input);
332	}
333	
334	/**
335	 * Branch-level DSA for the tree arm: instead of attending to every branch
336	 * summary in Zone B, keep only the top-k branches by
337	 *
338	 *   score(branch) = α·recency + β·lexical overlap of its summary with the task
339	 *
340	 * recency = creation-order index / count. The task root is exempt (the anchor
341	 * Zone B never drops) and the active branch is exempt (its detail is Zone C).
342	 * Selection changes MEMBERSHIP only — kept branches render in creation order,
343	 * so the Zone B prefix stays as stable as the tree's own rule 1 allows.
344	 *
345	 * The eval-floor property the design requires: k >= branch count returns
346	 * `undefined` — "no selection" — so short problems take the exact same code
347	 * path as the plain tree arm and there is no cache perturbation to pay for.
348	 */
349	const TREE_DSA_TOP_K_BRANCHES = 3;
350	const TREE_DSA_RECENCY_WEIGHT = 1;
351	const TREE_DSA_RELEVANCE_WEIGHT = 4;
352	const TREE_DSA_DIVERSITY_WEIGHT = 2;
353	
354	/** Lowercased, stopword-filtered term counts (same tokenizer as contentWords). */
355	export function termCounts(text: string): Map<string, number> {
356	  const out = new Map<string, number>();
357	  for (const word of contentWords(text)) out.set(word, (out.get(word) ?? 0) + 1);
358	  return out;
359	}
360	
361	/** Cosine similarity between two weighted term vectors. */
362	export function cosineSimilarity(a: Map<string, number>, b: Map<string, number>): number {
363	  let dot = 0;
364	  let normA = 0;
365	  let normB = 0;
366	  for (const value of a.values()) normA += value * value;
367	  for (const value of b.values()) normB += value * value;
368	  for (const [term, value] of a) {
369	    const other = b.get(term);
370	    if (other !== undefined) dot += value * other;
371	  }
372	  if (normA === 0 || normB === 0) return 0;
373	  return dot / Math.sqrt(normA * normB);
374	}
375	
376	/**
377	 * idf-weighted TF vectors over a corpus (here: the branch summaries) plus the
378	 * query. This is the "latent space" the DSA selector works in — a deterministic
379	 * lexical vector space (cosine / KNN-adjacent) with no embedding API call and
380	 * no LLM tokens: relevance = cosine(branch, task).
381	 */
382	export function idfVectors(
383	  texts: readonly string[],
384	  queryTerms: ReadonlySet<string>,
385	): { vectors: Map<string, number>[]; query: Map<string, number> } {
386	  const raw = texts.map(termCounts);
387	  const df = new Map<string, number>();
388	  const bump = (terms: Map<string, number>): void => {
389	    for (const term of terms.keys()) df.set(term, (df.get(term) ?? 0) + 1);
390	  };
391	  for (const terms of raw) bump(terms);
392	  const querySource = termCounts(Array.from(queryTerms).join(' '));
393	  bump(querySource);
394	  const n = raw.length + 1;
395	  const idf = (term: string): number => 1 + Math.log(n / (1 + (df.get(term) ?? 0)));
396	  const weighted = (terms: Map<string, number>): Map<string, number> => {
397	    const out = new Map<string, number>();
398	    for (const [term, count] of terms) out.set(term, count * idf(term));
399	    return out;
400	  };
401	  return { vectors: raw.map(weighted), query: weighted(querySource) };
402	}
403	
404	export function selectTopKBranches(
405	  branches: readonly { id: string; text: string }[],
406	  taskWords: Set<string>,
407	  k: number,
408	): ReadonlySet<string> | undefined {
409	  if (branches.length <= k) return undefined;
410	  const { vectors, query } = idfVectors(branches.map((branch) => branch.text), taskWords);
411	  const scored = branches.map((branch, i) => {
412	    const recency = (i + 1) / branches.length;
413	    const relevance = cosineSimilarity(vectors[i]!, query);
414	    return { branch, index: i, recency, relevance };
415	  });
416	  // Greedy farthest-point (max-min diversity) sampling: pick the best branch
417	  // first, then repeatedly the branch that is relevant/recency-strong AND
418	  // semantically furthest (smallest cosine) from the picks so far. Top-k by
419	  // score alone over-selects near-duplicate relevant branches; spreading the
420	  // kept branches is the DSA-style sparse-attention move, done in the vector
421	  // space instead of with an embedding model's tokens.
422	  const selected: number[] = [];
423	  while (selected.length < k) {
424	    let best = -1;
425	    let bestScore = -Infinity;
426	    for (let i = 0; i < scored.length; i++) {
427	      if (selected.includes(i)) continue;
428	      const candidate = scored[i]!;
429	      const minCosine =
430	        selected.length === 0
431	          ? 0
432	          : Math.min(...selected.map((picked) => cosineSimilarity(vectors[i]!, vectors[picked]!)));
433	      const diversity = 1 - minCosine;
434	      const score =
435	        TREE_DSA_RECENCY_WEIGHT * candidate.recency +
436	        TREE_DSA_RELEVANCE_WEIGHT * candidate.relevance +
437	        TREE_DSA_DIVERSITY_WEIGHT * diversity;
438	      if (score > bestScore) {
439	        bestScore = score;
440	        best = i;
441	      }
442	    }
443	    selected.push(best);
444	  }
445	  return new Set(selected.map((index) => branches[index]!.id));
446	}
447	
448	/**
449	 * Lazy-summarization policy for the tree arm. Awaited summarization on every
450	 * turn charges two model calls (leaf + root) against a trace whose raw events
451	 * still fit comfortably in Zone C — on short tasks the summarizer costs more
452	 * than the context it saves. So the arm summarizes only once enough new events
453	 * have accumulated to make a summary cheaper than the raw detail it replaces,
454	 * and reports how many summarize passes each run actually paid for.
455	 */
456	const SUMMARIZE_MIN_NEW_EVENTS = 8;
457	
458	/**
459	 * The summary circuit breaker's decision: split a summarization plan into the
460	 * nodes that should still run and the nodes to skip. A node whose summarization
461	 * broke the §8 contract already cost a full try+retry (two model calls) and
462	 * threw — re-processing it re-pays that for the identical failure, while fresh
463	 * siblings in the same plan still deserve their summary. §8's contract is that
464	 * a half-summarized tree is still usable, so skipping is graceful degradation,
465	 * not a correctness loss.
466	 */
467	export function splitSummarizePlan(
468	  plan: readonly string[],
469	  failed: ReadonlySet<string>,
470	): { pending: string[]; skipped: number } {
471	  const pending = plan.filter((nodeId) => !failed.has(nodeId));
472	  return { pending, skipped: plan.length - pending.length };
473	}
474	
475	/**
476	 * Optional Zone B branch filter for the tree arm, evaluated each turn BEFORE
477	 * assemble(). Returning `undefined` means "no selection" — the plain tree
478	 * path, byte-identical prompt. This is the seam the tree-dsa arm hangs its
479	 * top-k branch sampling on without forking the loop.
480	 */
481	type BranchSelector = (handle: TaskStore, activeNodeId: string | undefined) => ReadonlySet<string> | undefined;
482	
483	/** The tree-dsa arm's selector: top-k branch summaries by recency + task relevance. */
484	function makeTreeDsaSelector(task: string): BranchSelector {
485	  const taskWords = contentWords(task);
486	  return (handle, activeNodeId) => {
487	    const rootId = handle.store.root()?.id;
488	    const branches = handle.store
489	      .nodesInCreationOrder()
490	      .filter((node) => node.id !== rootId && node.id !== activeNodeId && node.parent_id === rootId)
491	      .map((node) => ({
492	        id: node.id as string,
493	        text: `${node.title}\n${handle.store.currentSummary(node.id)?.text ?? ''}`,
494	      }));
495	    return selectTopKBranches(branches, taskWords, TREE_DSA_TOP_K_BRANCHES);
496	  };
497	}
498	
499	async function runTreeArm(
500	  args: ArmArgs & { summarizerProvider: ModelProvider; selectBranches?: BranchSelector },
501	): Promise<ArmOutput> {
502	  const handle = openTaskStore(args.config);
503	  try {
504	    const summarizer = new Summarizer({
505	      store: handle.store,
506	      provider: args.summarizerProvider,
507	      leafModel: args.options.leafModel,
508	      rootModel: args.options.rootModel,
509	      trace: handle.trace,
510	      blobs: handle.blobs,
511	      maxSummaryTokens: 1024,
512	    });
513	    const retriever = new TreeRetriever({ store: handle.store, blobs: handle.blobs, trace: handle.trace });
514	    const toolCtx: ToolContext = { config: args.config, handle, retriever };
515	    const guard = makeRepeatGuard();
516	    const assembler = new ZoneAssembler({
517	      store: handle.store,
518	      blobs: handle.blobs,
519	      trace: handle.trace,
520	      tokenizer: new HeuristicTokenizer(),
521	      systemContract: systemContract() + TREE_COMPLETION_ADDENDUM,
522	      budgets: { ...args.options.budgets },
523	    });
524	
525	    const ts = () => new Date().toISOString();
526	    appendTo(handle, { type: 'user_message', ts: ts(), blob: handle.blobs.put(args.scenario.task) });
527	    // Lazy summarization (see SUMMARIZE_MIN_NEW_EVENTS): a one-event trace has
528	    // nothing to summarize — Zone C carries the raw event within budget. The
529	    // first summarize pass waits until enough events exist to be worth two
530	    // model calls.
531	    let newEventsSinceSummary = 1;
532	    // Summary circuit breaker: record nodes whose summarization broke the §8
533	    // contract (each failure = a full try+retry, two model calls) and exclude
534	    // them from later plans while still summarising fresh siblings — via the
535	    // D11 per-node scheduler (scheduleSummarize + drain), which preserves the
536	    // plan's leaves-then-root order on its promise chain.
537	    const failedSummaryNodes = new Set<string>();
538	    const maybeResummarize = async (): Promise<void> => {
539	      if (newEventsSinceSummary < SUMMARIZE_MIN_NEW_EVENTS) return;
540	      const rootId = handle.store.root()?.id;
541	      const plan = rootId === undefined ? [] : summarizer.stalePlan(rootId);
542	      const { pending, skipped } = splitSummarizePlan(plan, failedSummaryNodes);
543	      if (skipped > 0) {
544	        process.stderr.write(
545	          `[eval] summary circuit breaker: skipping ${skipped} node(s) that already failed the §8 contract once\n`,
546	        );
547	      }
548	      if (pending.length === 0) {
549	        newEventsSinceSummary = 0;
550	        return;
551	      }
552	      const before = summarizer.backgroundOutcomes().length;
553	      for (const nodeId of pending) summarizer.scheduleSummarize(nodeId);
554	      await summarizer.drain();
555	      for (const outcome of summarizer.backgroundOutcomes().slice(before)) {
556	        if (outcome.status === 'failed') {
557	          failedSummaryNodes.add(outcome.nodeId);
558	          process.stderr.write(
559	            `[eval] summarization failed on ${outcome.nodeId} (${outcome.role}): ${outcome.error?.message ?? 'unknown error'}\n`,
560	          );
561	        }
562	      }
563	      newEventsSinceSummary = 0;
564	    };
565	
566	    const treeTools = [...HARNESS_TOOL_SCHEMAS, ...CONTEXT_TOOL_SCHEMAS];
567	    let finalText = '';
568	    let tailCounter = 0;
569	    // Completion-gate state (see the bare-text branch below).
570	    let toolWorkDone = false;
571	    let completionConfirmed = false;
572	    for (let turnIndex = 0; turnIndex < args.options.maxTurns; turnIndex += 1) {
573	      if (Date.now() >= args.deadlineMs) return { status: 'time_cap', finalText };
574	      const activeNodeId = handle.store.openPhase()?.id ?? handle.store.root()?.id;
575	      const keepBranches = args.selectBranches?.(handle, activeNodeId);
576	      if (args.selectBranches !== undefined) {
577	        // Telemetry: whether branch sampling fired this turn, and how much it kept.
578	        const total = handle.store.nodesInCreationOrder().filter((n) => n.parent_id === handle.store.root()?.id).length;
579	        process.stderr.write(
580	          `[tree-dsa] turn ${turnIndex}: ${keepBranches === undefined ? `all ${total} branches (within k)` : `kept ${keepBranches.size}/${total} branches`}\n`,
581	        );
582	      }
583	      const prompt = assembler.assemble({
584	        toolSchemasText: TREE_ZONE_A_TOOL_SCHEMAS_TEXT,
585	        // appendEvent re-ingests the whole log each turn, and the segmenter ends
586	        // every trace by closing all phases and the task node — so openPhase()
587	        // is ALWAYS null here and the assembler would emit an empty Zone C (the
588	        // investigate-1 root cause: the model never saw its own tool results and
589	        // looped on stale summaries). Zone C must not vanish: expand the root,
590	        // which spans the whole trace.
591	        activeNodeId,
592	        selection: keepBranches === undefined ? undefined : { keepBranches },
593	      });
594	      const request = toCompletionRequest(prompt, args.options.model, {
595	        tools: treeTools,
596	        maxTokens: AGENT_MAX_TOKENS,
597	      });
598	      const { result, record } = await callModel({
599	        provider: args.provider,
600	        request,
601	        turnIndex,
602	        runHandle: args.runHandle,
603	        usage: args.usage,
604	      });
605	      args.turns.push(record);
606	      Object.assign(args.usage, addTotals(args.usage, result.usage));
607	
608	      const openBefore = handle.store.openPhase()?.id ?? null;
609	      const assistantEvent = appendTo(handle, {
610	        type: 'assistant_message',
611	        ts: ts(),
612	        blob: handle.blobs.put(result.text),
613	      });
614	      if (result.toolCalls.length === 0) {
615	        // Completion gate (iter 3): a bare-text reply right after tool work can
616	        // be premature completion — the thin early tree prompt lacks the "look
617	        // how much is still undone" signal native's growing transcript gives.
618	        // The first such reply gets one ephemeral nudge; only a SECOND
619	        // consecutive bare-text reply ends the run. Costs one cheap cached
620	        // turn exactly when the failure mode would otherwise fire.
621	        if (toolWorkDone && !completionConfirmed) {
622	          completionConfirmed = true;
623	          tailCounter += 1;
624	          assembler.appendTail({
625	            id: `completion-check-${tailCounter}`,
626	            text: 'system: you stopped calling tools. If every step of the task is verifiably done, reply with your final answer again; otherwise continue working.',
627	            ephemeral: true,
628	          });
629	          newEventsSinceSummary += 1;
630	          await maybeResummarize();
631	          continue;
632	        }
633	        finalText = result.text;
634	        // No end-of-run summarize pass: refreshing the tree for a hypothetical
635	        // next resumer is D11 sleep-time compute (`scheduleSummarize`), not
636	        // part of this run's critical path — and this sandbox is discarded
637	        // anyway. Charging it to the run would bill maintenance as task work.
638	        return { status: 'completed', finalText };
639	      }
640	      toolWorkDone = true;
641	      for (const call of result.toolCalls) {
642	        if (isHarnessTool(call.name)) {
643	          const outcome = await guard(call, () => executeHarnessTool(args.sandbox, call.name, call.input));
644	          const contentBlob =
645	            outcome.postContent !== undefined ? handle.blobs.put(outcome.postContent) : undefined;
646	          const callEvent = appendTo(handle, {
647	            type: 'tool_call',
648	            ts: ts(),
649	            tool: call.name,
650	            path: pathOf(call.input),
651	            args_blob: handle.blobs.put(JSON.stringify(call.input)),
652	            blob: contentBlob,
653	            parent_seq: assistantEvent.event.seq,
654	          });
655	          appendTo(handle, {
656	            type: 'tool_result',
657	            ts: ts(),
658	            call_seq: callEvent.event.seq,
659	            output_blob: handle.blobs.put(outcome.output),
660	            error: outcome.isError ? outcome.output.slice(0, 500) : undefined,
661	          });
662	          newEventsSinceSummary += 2;
663	        } else if (isContextTool(call.name)) {
664	          const outcome = await HANDLERS[call.name as ToolName](toolCtx, call.input);
665	          const text = outcome.ok
666	            ? JSON.stringify(outcome.data)
667	            : `error ${outcome.error.code}: ${outcome.error.message}`;
668	          tailCounter += 1;
669	          assembler.appendTail({ id: `${call.name}-${tailCounter}`, text, ephemeral: true });
670	        } else {
671	          tailCounter += 1;
672	          assembler.appendTail({
673	            id: `unknown-tool-${tailCounter}`,
674	            text: `error invalid_input: unknown tool ${call.name}`,
675	            ephemeral: true,
676	          });
677	        }
678	      }
679	      newEventsSinceSummary += 1; // the assistant message itself
680	      await maybeResummarize();
681	      const openAfter = handle.store.openPhase()?.id ?? null;
682	      if (openAfter !== openBefore) assembler.onPhaseTransition();
683	    }
684	    return { status: 'turn_cap', finalText };
685	  } finally {
686	    handle.close();
687	  }
688	}
689	
690	
691	export async function runScenario(loop: LoopOptions): Promise<LoopOutput> {
692	  const { scenario, arm, options } = loop;
693	  const label = `${scenario.benchmark}-${scenario.id}`;
694	  const sandbox = createSandbox(scenario, label);
695	  const startedAt = new Date();
696	  const turns: TurnRecord[] = [];
697	  const usage: TokenTotals = { ...ZERO_TOTALS };
698	  const costMeter = new InMemoryCostMeter({ capUsd: options.costCapUsd });
699	  const meteredAgent = new MeteredProvider(loop.agentProvider, costMeter);
700	  const meteredSummarizer = new MeteredProvider(loop.summarizerProvider ?? loop.agentProvider, costMeter);
701	
702	  const runHandle = loop.sink.startRun({
703	    runId: loop.runId,
704	    benchmark: scenario.benchmark,
705	    scenarioId: scenario.id,
706	    arm,
707	    model: options.model,
708	    scenarioTask: scenario.task,
709	    meta: { judgeKind: scenario.judge.kind, ...(scenario.meta ?? {}) },
710	  });
711	
712	  let status: RunStatus = 'error';
713	  let errorText: string | undefined;
714	  let finalText = '';
715	  let success: boolean | null = null;
716	  let judgeDetail = '';
717	
718	  try {
719	    const config = resolveConfig({
720	      root: join(sandbox.path, '.context-tree'),
721	      provider: options.provider,
722	      leafModel: options.leafModel,
723	      rootModel: options.rootModel,
724	      judgeModel: options.judgeModel,
725	      budgets: { ...options.budgets },
726	      taskTitle: `${scenario.benchmark}/${scenario.id}`,
727	    });
728	    const armArgs: ArmArgs = {
729	      scenario,
730	      config,
731	      options,
732	      provider: meteredAgent,
733	      sandbox,
734	      turns,
735	      usage,
736	      runHandle,
737	      deadlineMs: startedAt.getTime() + options.timeCapMs,
738	    };
739	    const output =
740	      arm === 'native'
741	        ? await runNativeArm(armArgs)
742	        : arm === 'dsa'
743	          ? await runDsaArm(armArgs)
744	          : arm === 'tree-dsa'
745	            ? await runTreeArm({
746	                ...armArgs,
747	                summarizerProvider: meteredSummarizer,
748	                selectBranches: makeTreeDsaSelector(scenario.task),
749	              })
750	            : await runTreeArm({ ...armArgs, summarizerProvider: meteredSummarizer });
751	    status = output.status;
752	    finalText = output.finalText;
753	  } catch (error) {
754	    if (error instanceof CostCapExceededError) {
755	      status = 'cost_cap';
756	    } else {
757	      errorText = `${(error as Error).name}: ${(error as Error).message}`;
758	    }
759	  }
760	
761	  if (errorText === undefined && (status === 'completed' || status === 'turn_cap' || status === 'time_cap')) {
762	    try {
763	      const judge = await judgeScenario({
764	        scenario,
765	        sandbox,
766	        finalText,
767	        provider: meteredAgent,
768	        judgeModel: options.judgeModel,
769	      });
770	      success = judge.success;
771	      judgeDetail = judge.detail;
772	    } catch (error) {
773	      if (error instanceof CostCapExceededError) {
774	        status = 'cost_cap';
775	      } else {
776	        errorText = `judge: ${(error as Error).name}: ${(error as Error).message}`;
777	      }
778	    }
779	  }
780	
781	  const finishedAt = new Date();
782	  const wallMs = finishedAt.getTime() - startedAt.getTime();
783	  const metrics = summarizeMetrics({ turns, wallMs, usage, costUsd: costMeter.totalUsd() });
784	  runHandle.finish(status, metrics, success, judgeDetail);
785	  if (options.keepSandbox) sandbox.writeFile('.final-answer.txt', finalText);
786	  else sandbox.cleanup();
787	
788	  const result: RunResult = {
789	    runId: loop.runId,
790	    benchmark: scenario.benchmark,
791	    scenarioId: scenario.id,
792	    arm,
793	    model: options.model,
794	    status,
795	    success,
796	    judge: { success, detail: judgeDetail },
797	    metrics,
798	    turns: [...turns],
799	    error: errorText,
800	    sandboxPath: options.keepSandbox ? sandbox.path : undefined,
801	    startedAt: startedAt.toISOString(),
802	    finishedAt: finishedAt.toISOString(),
803	  };
804	  return { result, finalText };
805	}
