264	  private zoneC(
265	    active: TreeNode | null,
266	    budget: number,
267	  ): { blocks: PromptBlock[]; truncated: boolean } {
268	    if (active === null) return { blocks: [], truncated: false };
269	    const { store, blobs, trace } = this.deps;
270	
271	    const blocks = [
272	      this.block(
273	        'C',
274	        `C:head:${active.id}`,
275	        renderActiveHeader(active, store.descendants(active.id)),
276	        active.id,
277	      ),
278	    ];
279	
280	    if (active.span_start_seq !== null) {
281	      const from = active.span_start_seq;
282	      const recorded = active.span_end_seq ?? from;
283	      const to = active.status === 'open' ? Math.max(recorded, trace.lastSeq()) : recorded;
284	      for (const event of trace.read({ from, to })) {
285	        blocks.push(this.block('C', `C:event:${event.seq}`, renderEvent(event, blobs)));
286	      }
287	    }
288	
289	    return { blocks, truncated: this.fitZoneC(blocks, budget) };
290	  }
291	
292	  /**
293	   * Rule 4: when Zone C is over budget, truncate the LARGEST detail blocks. Cap
294	   * chosen by water-filling (smallest cap `c` where `sum(min(tokens, c))` fits),
295	   * so the cost falls on the blocks actually responsible for the overflow and
296	   * small blocks survive intact. Returns whether anything was truncated.
297	   */
298	  private fitZoneC(blocks: PromptBlock[], budget: number): boolean {
299	    const total = sumTokens(blocks);
300	    if (total <= budget) return false;
301	
302	    const fill = (cap: number): number =>
