1	/**
2	 * §10 — cache-aware prompt assembly (D5).
3	 *
4	 * The layout is fixed and the content migrates through it:
5	 *
6	 *   Zone A  system contract + MCP tool schemas      frozen, cached permanently
7	 *   Zone B  task root summary, then branch summaries in CREATION ORDER
8	 *   Zone C  the ACTIVE branch expanded in full + this turn's tool results
9	 *   tail    `context_fetch`/`context_search`/`context_peek` output (D6)
10	 *
11	 * The single idea the whole file exists to protect: provider caches are keyed on
12	 * a *prefix*, so an edit in the middle invalidates everything after it. Zone B is
13	 * therefore never relevance-ordered (§10 rule 1) — relevance is expressed by
14	 * expansion in Zone C, and new summaries land at the END of Zone B where they
15	 * invalidate only the suffix that Zone C rewrites anyway (rule 2). Retrieval
16	 * results go after Zone C (rule 3) for the same reason.
17	 *
18	 * Block ids are stable functions of content coordinates (node id + summary
19	 * version, or L0 seq), because §17's cache-assertion harness proves "which
20	 * prefix ranges survived this event" by comparing ids and token counts across
21	 * two assemblies. If an id moved for a reason unrelated to content, that harness
22	 * silently stops testing anything.
23	 */
24	import { DEFAULT_CONFIG } from '../config.js';
25	import { StoreInvariantError } from '../contracts/index.js';
26	import type {
27	  AssembleOptions,
28	  AssembledPrompt,
29	  BlobStore,
30	  BudgetReport,
31	  ChatMessage,
32	  CompletionRequest,
33	  NodeId,
34	  PromptAssembler,
35	  PromptBlock,
36	  TailEntry,
37	  Tokenizer,
38	  ToolSchema,
39	  TraceLog,
40	  TreeNode,
41	  TreeStore,
42	  Zone,
43	} from '../contracts/index.js';
44	import {
45	  renderActiveHeader,
46	  renderActiveMap,
47	  renderEvent,
48	  renderLinksBlock,
49	  renderSummaryBlock,
50	  renderTailBlock,
51	  truncateToTokens,
52	} from './format.js';
53	
54	export interface ZoneAssemblerDeps {
55	  store: TreeStore;
56	  blobs: BlobStore;
57	  /**
58	   * L0 is required, not optional: Zone C is "the active branch's raw detail",
59	   * and L1 stores only the seq coordinates of that detail (§6).
60	   */
61	  trace: TraceLog;
62	  tokenizer: Tokenizer;
63	  /**
64	   * Zone A's frozen text. Byte-identical across every turn of a session — any
65	   * per-turn value leaking in here (a timestamp, a node count, a budget number)
66	   * permanently defeats caching for the whole session.
67	   */
68	  systemContract: string;
69	  budgets?: { zoneB: number; zoneC: number };
70	}
71	
72	/** A Zone B node contributes a summary block plus an optional links block; the
73	 *  pair is kept or dropped as a unit so a dropped summary never leaves orphan
74	 *  link annotations pointing at prose the model cannot see. */
75	interface ZoneBEntry {
76	  nodeId: NodeId;
77	  isRoot: boolean;
78	  blocks: PromptBlock[];
79	  tokens: number;
80	}
81	
82	export interface ZoneBSelection {
83	  /**
84	   * Branch ids to keep in Zone B, chosen by the caller (e.g. a DSA-style
85	   * top-k selector in the eval harness). `undefined` keeps every branch —
86	   * so k >= branch count and no selection at all are the same code path and
87	   * neither perturbs the prefix. The task root and the active branch are not
88	   * selectable: the root is the anchor and the active branch never appears in
89	   * Zone B anyway. Selected branches keep creation order (rule 1) — selection
90	   * changes membership, never position.
91	   */
92	  keepBranches?: ReadonlySet<NodeId>;
93	}
94	
95	export class ZoneAssembler implements PromptAssembler {
96	  private readonly deps: ZoneAssemblerDeps;
97	  private readonly budgets: { zoneB: number; zoneC: number };
98	  /** D6 soft offloading: fetched detail lives here and dies at a phase boundary. */
99	  private tail: TailEntry[] = [];
100	
101	  constructor(deps: ZoneAssemblerDeps) {
102	    this.deps = deps;
103	    this.budgets = deps.budgets ?? { ...DEFAULT_CONFIG.budgets };
104	  }
105	
106	  /** Appends one retrieval result to the tail (after Zone C — rule 3). */
107	  appendTail(entry: TailEntry): void {
108	    this.tail.push(entry);
109	  }
110	
111	  tailEntries(): readonly TailEntry[] {
112	    return this.tail;
113	  }
114	
115	  /**
116	   * D6: fetched branches die at phase boundaries. This drops the ephemeral tail
117	   * entries and does nothing else — in particular it does not touch L1, does not
118	   * close or open a node, and does not re-summarize. Phase state belongs to the
119	   * segmenter; the assembler only reads it.
120	   */
121	  onPhaseTransition(): void {
122	    this.tail = this.tail.filter((entry) => !entry.ephemeral);
123	  }
124	
125	  assemble(options: AssembleOptions = {}): AssembledPrompt {
126	    const { store } = this.deps;
127	    const root = store.root();
128	
129	    const activeNodeId = options.activeNodeId ?? store.openPhase()?.id ?? null;
130	    const active = activeNodeId === null ? null : store.getNode(activeNodeId);
131	    if (activeNodeId !== null && active === null) {
132	      throw new StoreInvariantError(`assemble: unknown activeNodeId ${activeNodeId}`);
133	    }
134	
135	    const zoneA = this.zoneA(options.toolSchemasText);
136	
137	    const zoneBBudget = options.zoneBBudget ?? this.budgets.zoneB;
138	    const zoneB = this.zoneB(root, this.activeBranchId(active, root), zoneBBudget, options.selection);
139	
140	    const zoneCBudget = options.zoneCBudget ?? this.budgets.zoneC;
141	    const zoneC = this.zoneC(active, zoneCBudget);
142	
143	    const tailBlocks = (options.tail ?? this.tail).map((entry) =>
144	      this.block('tail', `tail:${entry.id}`, renderTailBlock(entry.id, entry.text, entry.ephemeral)),
145	    );
146	
147	    // Rule 5: breakpoints at the Zone A/B and Zone B/C boundaries, nowhere else.
148	    const cacheBreakpoints: string[] = [];
149	    for (const zoneBlocks of [zoneA, zoneB.blocks]) {
150	      const last = zoneBlocks.at(-1);
151	      if (last === undefined) continue;
152	      last.cacheBreakpointAfter = true;
153	      cacheBreakpoints.push(last.id);
154	    }
155	
156	    const overBudget: Zone[] = [];
157	    // The asymmetry is deliberate: Zone B reports its degradation through
158	    // `droppedFromZoneB`, so `overBudget` only names it when dropping was not
159	    // enough. Zone C has no dropped-list field, so truncation is reported here —
160	    // a silent drop or truncation is indistinguishable from a summarizer bug.
161	    if (zoneB.tokens > zoneBBudget) overBudget.push('B');
162	    if (zoneC.truncated) overBudget.push('C');
163	
164	    const tailTokens = sumTokens(tailBlocks);
165	    const budgets: BudgetReport = {
166	      zoneA: sumTokens(zoneA),
167	      zoneB: zoneB.tokens,
168	      zoneC: sumTokens(zoneC.blocks),
169	      tail: tailTokens,
170	      total: 0,
171	      overBudget,
172	      droppedFromZoneB: zoneB.dropped,
173	    };
174	    budgets.total = budgets.zoneA + budgets.zoneB + budgets.zoneC + budgets.tail;
175	
176	    return {
177	      system: zoneA.map((b) => b.text).join('\n\n'),
178	      blocks: [...zoneA, ...zoneB.blocks, ...zoneC.blocks, ...tailBlocks],
179	      budgets,
180	      cacheBreakpoints,
181	    };
182	  }
183	
184	  // ── zones ──────────────────────────────────────────────────────────────────
185	
186	  private zoneA(toolSchemasText: string | undefined): PromptBlock[] {
187	    const blocks = [this.block('A', 'A:system', this.deps.systemContract)];
188	    if (toolSchemasText !== undefined && toolSchemasText !== '') {
189	      blocks.push(this.block('A', 'A:tools', toolSchemasText));
190	    }
191	    return blocks;
192	  }
193	
194	  /**
195	   * Zone B in creation order (rule 1) from `nodesInCreationOrder()`, restricted
196	   * to the task root and its direct branches — deeper nodes are detail, reachable
197	   * by expansion in Zone C or by `context_fetch`, and putting them here would
198	   * spend the 8k budget on exactly the content Zone C already carries.
199	   */
200	  private zoneB(
201	    root: TreeNode | null,
202	    activeBranchId: NodeId | null,
203	    budget: number,
204	    selection?: ZoneBSelection,

