# DOM-shim smoke: run the page script with a minimal document to count rendered figures + appendix rows
import re, subprocess, json
s=open('reports/metrics/tree-vs-transcript.html').read()
script=re.findall(r'<script>([\s\S]*?)</script>', s)[-1]
shim = '''
const els=[];
function mkel(tag){return {tag,attrs:{},children:[],style:{},appendChild(c){this.children.push(c);return c;},setAttribute(k,v){this.attrs[k]=v;},addEventListener(){},textContent:'',innerHTML:'',classList:{add(){},remove(){}},querySelectorAll(){return[];},getBoundingClientRect(){return{left:0,top:0,width:800,height:300};}};}
const registry={};
global.document={
  createElementNS:(ns,tag)=>mkel(tag),
  createElement:(tag)=>mkel(tag),
  getElementById:(id)=>{registry[id]=registry[id]||mkel('div'); return registry[id];},
  addEventListener(){}, body:mkel('body'), documentElement:{getAttribute:()=>null,addEventListener(){}} ,
  querySelectorAll:()=>[], querySelector:()=>null,
};
global.window={matchMedia:()=>({matches:false,addEventListener(){}}),addEventListener(){}};
global.getComputedStyle=()=>({getPropertyValue:()=>'#888888'});
global.MutationObserver=class{observe(){}};
'''
open('/tmp/ct-smoke.mjs','w').write(shim+script+'''
console.log('figures rendered:', Object.keys(registry).filter(k=>k.startsWith('fig')).map(k=>k+':'+registry[k].children.length).join(', '));
const tbl=registry['all-runs-tbl'];
console.log('appendix rows appended:', tbl?tbl.children.length:'n/a');
console.log('POINTS length:', POINTS.length);
''')
print(subprocess.run(['node','/tmp/ct-smoke.mjs'],capture_output=True,text=True).stdout or subprocess.run(['node','/tmp/ct-smoke.mjs'],capture_output=True,text=True).stderr)
PYEOF
